select * from swap_front_position
where user_id = #{userId,jdbcType=BIGINT}
and source IS NULL

    and symbol = #{symbol,jdbcType=VARCHAR}


    and direction=#{direction,jdbcType=INTEGER}

order by create_time ASC

select * from swap_front_position
where user_id = #{userId,jdbcType=BIGINT}
and source IS NOT NULL

    and symbol = #{symbol,jdbcType=VARCHAR}


    and direction=#{direction,jdbcType=INTEGER}

order by create_time ASC
